# -*- coding: utf-8 -*-
"""Science Stage 7 · Unit 5 Food Chains and Food Webs – Read the lesson (shown below the video) and the lesson document (PDF).
Camday's own text, examples and questions; scope: Cambridge Lower Secondary Science 0893, Stage 7 (7Bs.01, 7Be.01, 7Be.02, 7SIC.05)."""
from maths_notes_v4.kit4 import H, I, Y, X, K, L, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))
CHAIN = lambda title, *steps: {"kind": "sciFlow", "title": title, "steps": [dict(zip(("t", "d", "icon"), s)) for s in steps]}


def WEB(nodes, edges, w=92):
    """a food web: nodes = [(x, y, name, colour?)], edges = [(eaten, eater)] – the arrow points to the eater"""
    return {"kind": "flow", "nodes": [dict(x=n[0], y=n[1], t=n[2], **({"c": n[3]} if len(n) > 3 else {})) for n in nodes], "edges": [list(e) + [""] for e in edges], "w": w}


GREEN = "#DFF4EA"

# =====================================================================================================
# 5.1 Microorganisms as decomposers · 7Bs.01, 7Be.01
# =====================================================================================================
READ["5.1"] = L(
    H("Where do the leaves go?",
      "Every year a big tree drops thousands of leaves. Yet the ground under an old forest is not buried metres deep in leaves.",
      "What happens to them? Write your idea, then read on."),
    I("What are microorganisms?",
      "**Micro** means very small; an **organism** is a living thing. Most **microorganisms** are a single cell, so we need a microscope to see them.",
      table=[["Group", "What they are like", "Examples"],
             ["**bacteria**", "single cells with no nucleus; found almost everywhere", "bacteria in soil, in yoghurt, in your gut"],
             ["**fungi**", "yeasts are single cells; moulds grow as fine threads", "bread mould, yeast"],
             ["**protists**", "single cells with a nucleus; some photosynthesise", "algae in ponds, Amoeba"]],
      then=["When millions grow together they form a **colony** – big enough to see, like the fuzzy mould on old fruit."]),
    I("Helpful and harmful microorganisms",
      "Microorganisms live in soil, water, air, plants and inside animals – including you.",
      table=[["Helpful", "Harmful"],
             ["gut bacteria help digest food", "mouth bacteria cause tooth decay"], ["yeast makes bread rise", "some fungi cause athlete's foot"],
             ["bacteria turn milk into yoghurt and cheese", "moulds spoil food"], ["decomposers recycle nutrients", "**pathogens** cause diseases such as cholera"]],
      then=["A microorganism that causes disease is a **pathogen**."]),
    I("Predict, watch, explain: mouldy bread",
      "Three slices of the same bread, each sealed in a bag, kept for six days:",
      table=[["Slice", "Conditions", "After six days"], ["A", "damp, warm (30 °C)", "covered in mould"], ["B", "damp, in a fridge (4 °C)", "a few small spots"], ["C", "dry, warm", "no mould"]],
      then=["Mould is a fungus. Microorganisms grow fastest where it is **warm and moist**. Cold slows them down and without water they cannot grow.",
            "That is why we keep food in a fridge, or dry it (dried fruit, rice, beans) to make it last longer."]),
    Y("Slowest to spoil",
      mcq("s7u05r11", "Where will cooked rice stay fresh for longest?",
          [("in a covered dish in the fridge", True, "Yes – the cold slows down microorganisms."), ("in a covered dish in a warm kitchen", False, "Warm, moist food is ideal for microorganisms."),
           ("in an open dish by a sunny window", False, "Warm, and open to microorganisms from the air."), ("in a damp cloth bag", False, "Moisture helps microorganisms grow.")],
          "What conditions do microorganisms need?", "Microorganisms grow best when warm and moist; cold slows them.")),
    I("Decomposition: nature's recycling",
      "Dead leaves, dead animals and animal waste are food for **decomposers** – bacteria and fungi.",
      fig={"kind": "sciCycle", "title": "Recycling nutrients", "steps": ["Plants take in mineral salts", "Plants and animals die", "Decomposers feed and respire", "Mineral salts released into the soil"],
           "centre": "decomposition"},
      then=["As decomposers feed and respire, they break dead matter down into simpler substances – **decomposition**. This releases **mineral salts** back into the soil, ready for plants to take in through their roots.",
            "Animals such as earthworms, woodlice and millipedes (**detritivores**) help by breaking dead matter into smaller pieces."]),
    I("Investigation: leaves in net bags",
      "Scientists put 50 g of dead leaves in each of several net bags on a forest floor and weighed one bag every two months.",
      fig={"kind": "linegraph", "x": {"min": 0, "max": 10, "step": 2, "label": "time (months)"}, "y": {"min": 0, "max": 50, "step": 10, "label": "mass of leaves (g)"},
           "series": [{"pts": [[0, 50], [2, 38], [4, 29], [6, 22], [8, 17], [10, 13]]}]},
      then=["The mass fell quickly at first, then more slowly. After 10 months the leaves had lost 37 g – about three quarters of their mass.",
            "Independent variable: time. Dependent variable: mass of leaves. Control variables: type of leaves, type of bag, place."]),
    Y("Read the graph",
      num("s7u05r12", "Use the graph. How many grams of leaf were lost in the first 4 months?", 21, "Read the mass at 0 and at 4 months, then subtract.",
          "50 − 29 = 21 g.", errs=[(29, "That is the mass left. Subtract it from 50 g.")])),
    I("Decomposers in an ecosystem",
      "An **ecosystem** is all the living things in an area together with the non-living parts: light, water, air, soil and temperature.",
      then=["Without decomposers, dead matter and waste would pile up and the soil would run out of mineral salts. The materials of life are recycled again and again; only **energy** has to keep coming in, as sunlight."]),
    K("Key points",
      "Microorganisms (bacteria, fungi, protists) are tiny, usually single-celled, and live everywhere.",
      "Some are helpful, some harmful; disease-causing ones are **pathogens**.",
      "Microorganisms grow best when **warm and moist** – fridges and drying preserve food.",
      "**Decomposers** break down dead matter and release **mineral salts** for plants: nature's recycling."),
    book=BK(
        [("microorganism", "a living thing too small to see without a microscope"), ("pathogen", "a microorganism that causes disease"),
         ("decomposer", "a microorganism that breaks down dead matter"), ("decomposition", "breaking down dead matter into simpler substances"),
         ("ecosystem", "the living things in an area and their non-living surroundings"), ("detritivore", "an animal that breaks dead matter into smaller pieces")],
        [], [],
        [Ex("Name the three main groups of microorganisms and give an example of each.", ans="bacteria (e.g. gut bacteria), fungi (e.g. yeast, mould), protists (e.g. Amoeba, algae)"),
         Ex("Give two helpful and two harmful effects of microorganisms.", ans="helpful: digest food, make bread / yoghurt, recycle nutrients; harmful: tooth decay, food spoilage, diseases"),
         Ex("Explain why dried fish can be kept for months but fresh fish goes bad in a day.", ans="Microorganisms need water to grow; drying removes the water."),
         Ex("Describe what decomposers do and why they are important.", ans="They feed on dead matter and waste and break it down, releasing mineral salts into the soil that plants need; without them dead matter would pile up."),
         Ex("In the net-bag investigation, predict the mass after 14 months and explain your prediction.", ans="Roughly 7–10 g: the mass keeps falling but more and more slowly.", think=True)],
        ["describe bacteria, fungi and protists", "give helpful and harmful examples of microorganisms", "explain the conditions microorganisms need",
         "explain how decomposers recycle nutrients"],
        look=["the mouldy bread results", "the recycling cycle"],
        note="Read it after the video: microorganisms, mouldy bread, decomposition and the leaf-bag data (answers at the back)."),
)

# =====================================================================================================
# 5.2 Food chains and food webs · 7Be.02, 7SIC.05
# =====================================================================================================
READ["5.2"] = L(
    H("Where does your energy come from?",
      "This morning you ate an egg. The hen ate grain. The grain grew in sunlight.",
      "So your energy started in the Sun. In this lesson you will learn to show this as a **food chain**."),
    I("Producers",
      "Plants and algae make their own food by **photosynthesis**: using light energy trapped by **chlorophyll**, they turn carbon dioxide and water into glucose and give out oxygen.",
      then=["An organism that makes its own food is a **producer**. Every food chain starts with a producer – all other organisms depend on it.",
            "Not all producers look green: red-leaved plants still have chlorophyll, hidden by red pigments."]),
    I("Consumers",
      "Animals cannot make their own food; they eat other organisms – they are **consumers**.",
      table=[["Kind of consumer", "Eats", "Example"], ["**herbivore**", "plants only", "cow, caterpillar"], ["**carnivore**", "animals only", "lion, spider"],
             ["**omnivore**", "plants and animals", "bear, human"]],
      then=["A **predator** hunts other animals; the hunted animal is its **prey**. An owl is a predator; a mouse is its prey."]),
    I("A food chain",
      "A **food chain** shows what eats what. The arrow means **'is eaten by'** and points the way **energy flows**.",
      fig=CHAIN("A rice-field food chain", ("rice", "producer"), ("grasshopper", "primary consumer"), ("frog", "secondary consumer"), ("heron", "tertiary consumer")),
      then=["Energy enters the chain as sunlight, trapped by the producer. It passes from the rice to the grasshopper, to the frog, to the heron.",
            "**Primary** consumers eat producers; **secondary** consumers eat primary consumers; **tertiary** consumers eat secondary consumers. Something that eats a tertiary consumer is a **quaternary** consumer."]),
    Y("Which way do the arrows go?",
      mcq("s7u05r21", "Which food chain is drawn correctly?",
          [("grass → zebra → lion", True, "Yes – the arrows point from the food to the eater."), ("lion → zebra → grass", False, "The arrows must show the way energy flows: from food to eater."),
           ("zebra → grass → lion", False, "A food chain starts with a producer."), ("grass ← zebra ← lion", False, "Arrows point towards the animal that eats.")],
          "Arrows mean 'is eaten by'.", "Grass is eaten by the zebra, which is eaten by the lion: grass → zebra → lion.")),
    I("Build a food chain",
      "Clues from a forest: a hawk eats snakes; mice eat seeds; snakes eat mice; an oak tree makes seeds.",
      table=[["Step", "Reasoning"], ["1", "start with the producer: **oak seeds**"], ["2", "what eats the seeds? **mouse** (primary consumer)"],
             ["3", "what eats the mouse? **snake** (secondary consumer)"], ["4", "what eats the snake? **hawk** (tertiary consumer, top of the chain)"]],
      then=["Food chain: **oak seeds → mouse → snake → hawk**."]),
    I("Food webs",
      "Most animals eat more than one thing, so food chains link up. All the linked chains in an ecosystem make a **food web**.",
      fig=WEB([(60, 280, "grass", GREEN), (240, 280, "maize", GREEN), (60, 180, "grasshopper"), (180, 180, "mouse"), (320, 180, "rabbit"), (120, 80, "frog"), (300, 80, "snake"), (430, 140, "eagle")],
              [(0, 2), (1, 3), (0, 4), (1, 4), (2, 5), (3, 6), (5, 6), (5, 7), (3, 7), (4, 7), (6, 7)]),
      then=["In a web an animal can be at more than one level: the eagle is a secondary consumer when it eats a mouse and a tertiary consumer when it eats a frog."]),
    I("Predict, watch, explain: if the frogs disappear",
      "Suppose a disease kills all the frogs in this web.",
      table=[["Organism", "Change", "Why"], ["grasshoppers", "increase", "nothing eats them now"], ["grass", "decreases", "more grasshoppers eat it"],
             ["snakes", "eat more mice", "they have lost one food source"], ["mice and rabbits", "decrease", "more are eaten, and there is less grass"]],
      then=["In a food web every organism is linked. Removing one species changes the food supply of its predators and its prey – the change ripples through the whole web."]),
    Y("Read the food web",
      grid("s7u05r22", "Use the food web. Which word describes each organism?", ["Producer", "Herbivore", "Carnivore"],
           [("maize", "Producer"), ("rabbit", "Herbivore"), ("snake", "Carnivore"), ("grasshopper", "Herbivore"), ("grass", "Producer")],
           "Producers make food; herbivores eat only plants; carnivores eat animals.", "Grass and maize are producers; rabbits and grasshoppers eat plants; snakes eat mice and frogs.")),
    I("Decomposers and microplastics",
      "Decomposers belong in every food web: they break down dead organisms and waste from **every** level.",
      then=["Food chains also pass on things that are **not** food. Tiny pieces of plastic (**microplastics**) are eaten by plankton, which are eaten by small fish, and so on up the chain – they have been found in seabirds, whales and even in food for people.",
            "Scientists are making plastics from plants that decomposers can break down into carbon dioxide and water."]),
    I("Science today: jellyfish swarms",
      "Warmer seas, caused by climate change, help jellyfish breed faster. Huge swarms appear on some coasts.",
      then=["More jellyfish eat more plankton, leaving less food for small fish – and fewer fish for seabirds, seals and dolphins. But turtles, which eat jellyfish, get more food. One change spreads through the whole ocean food web."]),
    K("Key points",
      "**Producers** make food by photosynthesis; **consumers** eat other organisms (herbivores, carnivores, omnivores).",
      "Food chain arrows mean **'is eaten by'** and show the direction of **energy flow**.",
      "Primary → secondary → tertiary → quaternary consumers.",
      "A **food web** is many linked food chains; changing one population affects many others.",
      "Decomposers break down dead matter at every level; microplastics pass along food chains."),
    book=BK(
        [("producer", "an organism that makes its own food, such as a plant"), ("consumer", "an organism that eats other organisms"),
         ("herbivore", "eats only plants"), ("carnivore", "eats only animals"), ("omnivore", "eats plants and animals"),
         ("food chain", "shows the transfer of energy from one organism to the next"), ("food web", "linked food chains in an ecosystem"),
         ("predator", "an animal that hunts other animals"), ("prey", "an animal that is hunted")],
        [], [],
        [Ex("What do the arrows in a food chain show?", ans="the direction energy flows – 'is eaten by'"),
         Ex("Aphids eat rose leaves, ladybirds eat aphids and birds eat ladybirds.", ("Write the food chain.", "rose → aphid → ladybird → bird"),
            ("Name the producer and the secondary consumer.", "rose; ladybird")),
         Ex("Use the food web in this lesson.", ("Name an animal that eats both mice and frogs.", "the snake (or eagle)"),
            ("What might happen to the rabbits if all the eagles were removed?", "they would increase at first, then there might be less grass")),
         Ex("Explain why every food chain begins with a producer.", ans="Only producers bring energy into the chain by trapping sunlight in photosynthesis; all consumers depend on them."),
         Ex("A farmer kills all the snakes on her farm. Predict and explain one effect on her maize crop.",
            ans="More mice survive, so more maize is eaten – the crop is smaller.", think=True)],
        ["explain producers and kinds of consumers", "construct and read food chains", "read food webs", "predict the effects of a change in a food web",
         "explain how microplastics pass along food chains"],
        look=["the rice-field food chain", "what happens when the frogs disappear"],
        note="Read it after the video: producers, consumers, food chains and webs, and changes in a web (answers at the back)."),
)
